/* vNN.xx, UI REDESIGN ui5q2g (his #50, from the AAA judge of the Last Pour shot): ONE PRIMARY AT THE BAR. Every drink had a solid
   amber INGEST (ui5q1o), so the window had two or more primary buttons and none of them stood out. INGEST is an amber outline
   button now, and the one under the mouse or the pad fills amber. */
#root #barmodal button[data-bz]:not(:disabled){ background:transparent; border-color:var(--acc); color:var(--acc); }
#root #barmodal button[data-bz]:not(:disabled):hover, #root #barmodal button[data-bz]:not(:disabled):focus-visible,
#root #barmodal button[data-bz].padfocus:not(:disabled){ background:var(--acc); border-color:var(--acc); color:var(--acc-ink); }
/* vNN.xx, UI REDESIGN ui5q1c (his #50, from the AAA judge

check:
{v:'VER',what:'his #50 (UI redesign ui5q2g): at the Last Pour an INGEST that can be paid is an outline button, not a second solid amber primary',
 run:function(){
   if(typeof renderBar!=='function') return 'SKIP: no bar here';
   var c0=P.credits, bad=[], q, i, b=null, n=0;
   try{
     P.credits=9999999; renderBar();
     q=document.querySelectorAll('#barmodal button[data-bz]');
     for(i=0;i<q.length;i++){ if(!q[i].disabled){ n++; if(!b&&!q[i].classList.contains('padfocus')&&document.activeElement!==q[i]) b=q[i]; } }
     if(n<2) return 'SKIP: fewer than two drinks can be bought here';
     if(!b) return 'SKIP: every INGEST is focused';
     var bg=getComputedStyle(b).backgroundColor;
     if(bg!=='rgba(0, 0, 0, 0)'&&bg!=='transparent') bad.push('an INGEST at rest is filled '+bg+', so '+n+' primaries share the window');
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   finally{ P.credits=c0; try{ renderBar(); }catch(_r){} }
   return bad.length?bad.join('; '):null; }},
